import os,json,stat,hashlib,errno,fcntl
# run19: run18 + write_all (advance by actual return, no-progress = error) in publisher copy and put; candidate readback (fstat size + pread sha) before pending/rename; put verifies JSON readback before rename.
# run18: run17 + rollback reorder (verify old committed, durable put(wm w/o pending), then unlink tmp) + promote gate refuses non-verified committed.
# run17: run16 + committed check on p=None. run16: run15 + single-fd obj() with post-read name/ctime check, flock around promote/recover.
# run15 note: recovery binds tmp/final to pending by (st_dev,st_ino) via lstat; unbound tmp is stray, never a rename witness.
N=66; EXPECT=hashlib.sha256(bytes(range(N))).hexdigest()
def H(p): return hashlib.sha256(open(p,'rb').read()).hexdigest()
def fsync_dir(d):
    fd=os.open(d,os.O_RDONLY|os.O_DIRECTORY); os.fsync(fd); os.close(fd)
class ShortWrite(Exception): pass
def write_all(fd,b):  # run19: write(2) may return < len; loop on the real count, 0 = no progress
    v=memoryview(b); off=0
    while off<len(v):
        n=os.write(fd,v[off:])
        if n<=0: raise ShortWrite(f"no_progress at {off}/{len(v)}")
        off+=n
    return off
def put(path,obj):
    t=path+'.tmp'; b=json.dumps(obj,sort_keys=True).encode()
    fd=os.open(t,os.O_RDWR|os.O_CREAT|os.O_TRUNC,0o600)
    try:
        write_all(fd,b); os.fsync(fd)
        if os.fstat(fd).st_size!=len(b) or os.pread(fd,len(b)+1,0)!=b: raise ShortWrite("put_readback_mismatch")
    except BaseException:
        os.close(fd); os.unlink(t); raise                       # wm untouched: rename never happened
    os.close(fd); os.rename(t,path); fsync_dir(os.path.dirname(path))
def get(path): return json.load(open(path))
def crash(at,name):
    if at==name: os._exit(77)
HOOK=None  # test-only: called between read and post-checks
def obj(p):  # run16: one fd binds (dev,ino) to bytes; then re-check name and ctime
    try: fd=os.open(p,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK|os.O_CLOEXEC)
    except FileNotFoundError: return None
    except OSError as e:
        if e.errno==errno.ELOOP: s=os.lstat(p); return {"dev":s.st_dev,"ino":s.st_ino,"reg":False,"len":s.st_size,"sha":None}
        raise
    try:
        s0=os.fstat(fd)
        if not stat.S_ISREG(s0.st_mode): return {"dev":s0.st_dev,"ino":s0.st_ino,"reg":False,"len":s0.st_size,"sha":None}
        h=hashlib.sha256()
        while (c:=os.read(fd,65536)): h.update(c)
        if HOOK: HOOK(p)
        s1=os.fstat(fd)
        try: sn=os.lstat(p)
        except FileNotFoundError: sn=None
    finally: os.close(fd)
    if (s1.st_ctime_ns,s1.st_size)!=(s0.st_ctime_ns,s0.st_size): raise Unstable("changed_during_read")
    if sn is None or (sn.st_dev,sn.st_ino)!=(s0.st_dev,s0.st_ino): raise Unstable("name_moved_during_read")
    return {"dev":s0.st_dev,"ino":s0.st_ino,"reg":True,"len":s0.st_size,"sha":h.hexdigest()}
class Unstable(Exception): pass
class Busy(Exception): pass
def locked(pubdir):  # advisory: excludes cooperating promote/recover only
    fd=os.open(os.path.join(pubdir,".lock"),os.O_RDWR|os.O_CREAT|os.O_CLOEXEC,0o600)
    try: fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB)
    except BlockingIOError: os.close(fd); raise Busy()
    return fd
def promote(staging,pubdir,wm,crash_at=None):
    lk=locked(pubdir)  # held until exit/crash; kernel drops it with the fd
    try: return _promote(staging,pubdir,wm,crash_at)
    finally: os.close(lk)
def _promote(staging,pubdir,wm,crash_at=None):
    w0=get(wm)
    final=os.path.join(pubdir,"final"); tmp=os.path.join(pubdir,".promote.tmp")
    if "pending" in w0: return "REFUSED pending recover_first"      # run18: gate under the same lock, before any tmp/pending
    if os.path.lexists(tmp): return "REFUSED stray_tmp recover_first"
    try: c=committed(obj(final),w0)
    except Unstable as e: return f"RETRY unstable {e}"
    if c not in ("verified","empty"): return f"REFUSED {c}"          # no auto-repair: wm/final left as evidence
    fd=os.open(staging,os.O_RDONLY|os.O_NONBLOCK|os.O_NOFOLLOW|os.O_CLOEXEC)
    st=os.fstat(fd)
    if not stat.S_ISREG(st.st_mode) or st.st_size!=N: os.close(fd); return "FAIL precheck"
    b=os.pread(fd,N+1,0); os.close(fd)
    if hashlib.sha256(b).hexdigest()!=EXPECT: return "FAIL content_mismatch"
    w=os.open(tmp,os.O_RDWR|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW|os.O_CLOEXEC,0o444)
    try:
        write_all(w,b); os.fsync(w); s=os.fstat(w)
        back=os.pread(w,N+1,0)                                      # run19: verify the candidate we will name, via the same fd
        if s.st_size!=N or hashlib.sha256(back).hexdigest()!=EXPECT: raise ShortWrite(f"candidate len={s.st_size}")
    except (OSError,ShortWrite) as e:
        os.close(w); os.unlink(tmp); fsync_dir(pubdir)               # no pending written yet: wm/final untouched
        return f"FAIL copy {type(e).__name__} {e}"
    os.close(w); fsync_dir(pubdir)
    rec={"gen":w0["gen"]+1,"sha":EXPECT,"dev":s.st_dev,"ino":s.st_ino}
    put(wm,{**w0,"pending":rec});                                   crash(crash_at,"after_pending")
    os.rename(tmp,final); fsync_dir(pubdir);                        crash(crash_at,"after_rename")
    put(wm,rec);                                                    crash(crash_at,"after_commit")
    return "PASS"
def bound(o,p): return o is not None and o["reg"] and (o["dev"],o["ino"])==(p["dev"],p["ino"]) and o["len"]==N and o["sha"]==p["sha"]
def committed(f,w):  # run17: does final match the committed wm (no pending)?
    if w["gen"]==0: return "empty" if f is None else "UNEXPECTED_final_at_gen0"
    if f is None: return "COMMITTED_MISSING"
    if bound(f,w): return "verified"
    return f"COMMITTED_MISMATCH (ino_match={(f['dev'],f['ino'])==(w['dev'],w['ino'])} sha_match={f['sha']==w['sha']})"
def recover(pubdir,wm,crash_at=None):
    try: lk=locked(pubdir)
    except Busy: return "BUSY"
    try: return _recover(pubdir,wm,crash_at)
    except Unstable as e: return f"RETRY unstable {e}"
    finally: os.close(lk)
def _recover(pubdir,wm,crash_at=None):
    w=get(wm); p=w.get("pending")
    final=os.path.join(pubdir,"final"); tmp=os.path.join(pubdir,".promote.tmp")
    t,f=obj(tmp),obj(final); note=""
    if p is None:                                                   # run17: clean = no open txn; then verify committed separately
        if t is not None: os.unlink(tmp); fsync_dir(pubdir); note=" +stray_tmp_removed"
        return "clean "+committed(f,w)+note
    if bound(t,p):                                                  # the pending object is still under tmp: rename not done
        w_old={k:v for k,v in w.items() if k!="pending"}
        c=committed(f,w_old)                                        # run18: is the state we roll back TO admissible?
        if c not in ("verified","empty"): return f"CORRUPT rollback_target {c}"   # keep tmp+pending+final as evidence
        put(wm,w_old);                                              crash(crash_at,"rb_after_put")  # durable first
        os.unlink(tmp); fsync_dir(pubdir);                          crash(crash_at,"rb_after_unlink")
        return "roll_back "+c
    if t is not None: os.unlink(tmp); fsync_dir(pubdir); note=" +stray_tmp_removed"   # tmp not ours: not a witness
    if f is None: return "CORRUPT pending_but_no_final"+note
    if bound(f,p): put(wm,{k:p[k] for k in ("gen","sha","dev","ino")}); return "roll_forward"+note
    return f"CORRUPT final_not_pending (ino_match={(f['dev'],f['ino'])==(p['dev'],p['ino'])} sha_match={f['sha']==p['sha']})"+note
```

