    st=root+"/staging"; open(st,"wb").write(bytes(range(R.N)))
    wm=root+"/pub/wm"; R.put(wm,{"gen":0,"sha":None,"dev":None,"ino":None})
    assert R.promote(st,root+"/pub",wm)=="PASS"
