    try: got=fn()
    except Exception as e: got=f"EXC {type(e).__name__} {e}"
    ok=got.startswith(expect); res.append(ok); print(f"[{name}] {got}  {'ok' if ok else 'MISMATCH expected '+expect}")
def with_hook(h,fn):
