# baseline matrix (same 7 as t15)
case("after_pending","roll_back verified",lambda:R.recover(*crashed("ap","after_pending")))
case("after_rename","roll_forward",lambda:R.recover(*crashed("ar")))
case("after_commit","clean verified",lambda:R.recover(*crashed("ac","after_commit")))
def fw(): pub,wm=crashed("fw"); inplace(pub+"/final"); return R.recover(pub,wm)
case("foreign_write","CORRUPT final_not_pending (ino_match=True sha_match=False)",fw)
